    if (!refs.has(m[1])) refs.set(m[1], []);
    refs.get(m[1])!.push(i + 1);
  }
});
const missing = [...refs.entries()].filter(([k]) => !defs.has(k)).map(([k, v]) => `${k} @${v.join(",")}`);
const dup = [...defs.entries()].filter(([, v]) => v.length > 1).map(([k, v]) => `${k} @${v.join(",")}`);
const code: string[] = [];
